import { useState } from 'react'
import { useEffect } from 'react'
import axios from 'axios'
import './Chatbot.css'
import { useAuthContext } from '../hooks/useAuthContext'
import { useNavigate } from 'react-router-dom'
import { useCallback } from 'react'


const Chatbot = () => {
  const [userInput, setUserInput] = useState('')
  const [chatMessages, setChatMessages] = useState([])
  const [conversations, setConversations] = useState([])
  
  const { user } = useAuthContext()
  const navigate = useNavigate()

  const viewConversations = useCallback(async () => {
    if (!user?.token) return; // ✅ safe guard inside the function

    try {
        const res = await axios.get('http://localhost:4000/api/chat', {
        headers: { Authorization: `Bearer ${user.token}` }
        });
        setConversations(res.data);
    } catch (err) {
        console.error('Failed to fetch history:', err);
    }
    }, [user?.token]);


  useEffect(() => {
    if (!user) {
      navigate('/auth')
    } else {
    viewConversations()
    }
  }, [user, navigate, viewConversations])

  if (!user) return null

  const sendMessage = async () => {
    if (userInput.trim() === '') return

    try {
      const response = await axios.post(
        'http://localhost:4000/api/chat',
        { message: userInput },
        {
          headers: {
            Authorization: `Bearer ${user.token}`
          }
        }
      )

      setChatMessages(prev => [
        ...prev,
        { text: userInput, isUser: true },
        { text: response.data.botResponse, isUser: false }
      ])
    } catch (error) {
      console.error('Error sending message', error)
    }

    setUserInput('')
  };

  

  return (
    <div className="chatbot">
      <div className="chat-window">
        {chatMessages.map((msg, index) => (
          <div key={index} className={msg.isUser ? 'user' : 'bot'}>
            {msg.text}
          </div>
        ))}
      </div>



      <input
        type="text"
        value={userInput}
        onChange={(e) => setUserInput(e.target.value)}
        placeholder="Type your message..."
      />
      <button onClick={sendMessage}>Send</button>
    </div>
    
  )
}

export default Chatbot
